-- P2: checkouts by member M-17
SELECT checkout_id, tool_id AS raw_tool_id, out_time, in_time, note, hours_marked
FROM checkout_record
WHERE member_id = 'member:M-17'
ORDER BY checkout_id;

-- Resolve historical tool identifiers via tool_identity_remap + tool_record
SELECT from_tool_id, to_tool_id FROM tool_identity_remap;
-- L1 -> tool:LASER-A

SELECT tool_id, name FROM tool_record;
-- Short ids CNC-1, LASER-A, SAW-1 map to tool:CNC-1, tool:LASER-A, tool:SAW-1
